<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class PayrollRun extends Model { use HasFactory; protected $fillable=['business_id','code','period_start','period_end','pay_date','branch_id','status','gross_compensation','adjustments_total','cash_advance_deductions','payroll_recovery_deductions','statutory_employee_deductions','statutory_employer_contributions','net_pay','notes','calculated_at','created_by','approved_by','approved_at','paid_by','paid_at','payment_account_id','payment_reference']; protected function casts():array{return['period_start'=>'immutable_date','period_end'=>'immutable_date','pay_date'=>'immutable_date','gross_compensation'=>'decimal:2','adjustments_total'=>'decimal:2','cash_advance_deductions'=>'decimal:2','payroll_recovery_deductions'=>'decimal:2','statutory_employee_deductions'=>'decimal:2','statutory_employer_contributions'=>'decimal:2','net_pay'=>'decimal:2','calculated_at'=>'immutable_datetime','approved_at'=>'immutable_datetime','paid_at'=>'immutable_datetime'];} public function lines():HasMany{return $this->hasMany(PayrollLine::class);} public function branch():BelongsTo{return $this->belongsTo(Branch::class);} public function paymentAccount():BelongsTo{return $this->belongsTo(ChartOfAccount::class,'payment_account_id');} public function paymentSplits():HasMany{return $this->hasMany(PayrollPaymentSplit::class,'payroll_run_id')->orderBy('sort_order')->orderBy('id');} public function cashAdvanceWaivers():HasMany{return $this->hasMany(PayrollCashAdvanceWaiver::class,'payroll_run_id');} public function recoveryAllocations():HasMany{return $this->hasMany(PayrollRecoveryAllocation::class,'payroll_run_id')->orderBy('id');} }
